use std::fs

fn eval(line: string) -> string {
    let mut st: Vec<i64> = Vec::new()
    for tok in line.split_whitespace() {
        if tok == "+" || tok == "-" || tok == "*" || tok == "/" {
            if st.len() < 2 {
                return "error: underflow"
            }
            let b = st.pop() ?? 0
            let a = st.pop() ?? 0
            if tok == "+" {
                st.push(a + b)
            } else if tok == "-" {
                st.push(a - b)
            } else if tok == "*" {
                st.push(a * b)
            } else {
                if b == 0 {
                    return "error: divzero"
                }
                st.push(a / b)
            }
        } else {
            match tok.parse::<i64>() {
                Ok(v) => st.push(v),
                Err(_) => return "error: token",
            }
        }
    }
    if st.len() != 1 {
        return "error: leftover"
    }
    st[0].to_string()
}

fn main() {
    let text = fs::read_to_string("/dev/stdin") ?? ""
    for line in text.lines() {
        if line.trim() == "" {
            continue
        }
        println(eval(line))
    }
}

